  [("What would you never buy online?", "อะไรที่ไม่มีวันซื้อออนไลน์?", "à-rai thîi mâi mii wan sʉ́ʉ ɔɔn-laai?"),
   ("Which store in your city do you like best?", "ชอบร้านไหนในเมืองเธอที่สุด?", "chɔ̂ɔp ráan nǎi nai mʉang thəə thîi-sùt?")],
